const all={...quant,...verbal};

export function getStage3CalibratedQuestions(activityId){
 const specs=all[activityId];
 if(!specs) throw new Error(`Stage 3 calibration: unknown activity ${activityId}`);
 const source=specs.map((item,index)=>q(activityId,index+1,...item));
 const prepared=prepareReasoningQuestionSet(source);
 const ids=new Set(prepared.map(item=>item.id));
 const invalidAnswers=prepared.filter(item=>!item.options.includes(item.answer));
 const duplicateOptions=prepared.filter(item=>new Set(item.options).size!==item.options.length);
 const lengthCues=prepared.filter(item=>item.optionQuality?.lengthCueDetected);
 if(prepared.length!==10||ids.size!==10||invalidAnswers.length||duplicateOptions.length||lengthCues.length){throw new Error(`Stage 3 question-set validation failed for ${activityId}: expected 10 unique valid questions with no length cues.`);}
 return prepared;
}
